SELECT p.gender, s.age, i.admission_type_id, i.discharge_location, i.death_date, i.length_of_stay, percentile_cont(0.5) within GROUP (ORDER BY i.length_of_stay) AS p50, percentile_cont(0.75) within GROUP (ORDER BY i.length_of_stay) AS p75, percentile_cont(0.90) within GROUP (ORDER BY i.length_of_stay) AS p90, AVG(i.length_of_stay) AS average_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.hadm_id = i.subject_id JOIN services s ON a.hadm_id = s.hadm_id WHERE p.gender = 'M' AND s.age BETWEEN 38 AND 48 AND i.admission_type_id = 1 AND i.discharge_location IN (1, 2) AND i.death_date IS NULL GROUP BY p.gender, s.age, i.admission_type_id, i.discharge_location, i.death_date ORDER BY p.gender, s.age, i.admission_type_id, i.discharge_location, i.death_date NULLS LAST;